void sig_handler(int sig) {
    // Control transfers from kernel to user space (ECF)
    write(STDOUT_FILENO, "Caught signal.\n", 15);
}

struct sigaction sa;
sa.sa_handler = sig_handler;
sigemptyset(&sa.sa_mask);
sa.sa_flags = 0;

// System Call: Register the signal handler
if (sigaction(SIGINT, &sa, NULL) < 0) {
    perror("sigaction error");
    exit(1);
}

// System Call: Wait for event/interrupt
pause();
